def tsp_min(dist):
    n = len(dist)
    used = [False] * n
    used[0] = True
    def dfs(last, depth, cost):
        if depth == n:
            return cost + dist[last][0]
        best = float('inf')
        for city in range(1, n):
            if not used[city]:
                used[city] = True
                value = dfs(city, depth + 1, cost + dist[last][city])
                best = min(best, value)
                used[city] = False
        return best
    return dfs(0, 1, 0)

