    int total=cost+d[last][0];
    if(total<*best) *best=total;
    return;
  }
  for(int next=1;next<n;next++) if(!used[next]) {
    used[next]=1;
    tsp_visit(d,n,depth+1,next,used,cost+d[last][next],best);
    used[next]=0;
  }
