def quick_select(a, k):
    lo, hi, target = 0, len(a) - 1, k - 1
    while lo <= hi:
        pivot, p = a[hi], lo
        for j in range(lo, hi):
            if a[j] <= pivot:
                a[p], a[j] = a[j], a[p]
                p += 1
        a[p], a[hi] = a[hi], a[p]
        if p == target:
            return a[p]
        if p < target:
            lo = p + 1
        else:
            hi = p - 1

