    int lo=0, hi=n-1, target=k-1;
    while (lo <= hi) {
        int pivot=a[hi], p=lo;
        for (int j=lo; j<hi; ++j) {
            if (a[j] <= pivot) {
                int t=a[p]; a[p++]=a[j]; a[j]=t;
            }
        }
        int t=a[p]; a[p]=a[hi]; a[hi]=t;
        if (p == target) return a[p];
        if (p < target) lo=p+1;
        else hi=p-1;
    }
    return 0; /* unreachable for valid k */
}

