long long cross_sum(const int a[], int lo, int mid, int hi) {
    long long sum=0, left=a[mid-1], right=a[mid];
    for (int i=mid-1; i>=lo; --i) {
        sum+=a[i];
        if (sum>left) left=sum;
    }
    sum=0;
    for (int i=mid; i<hi; ++i) {
        sum+=a[i];
        if (sum>right) right=sum;
    }
    return left+right;
}

