    if (hi-lo == 1) return a[lo];
    int mid=(lo+hi)/2;
    long long left=max_subarray(a,lo,mid);
    long long right=max_subarray(a,mid,hi);
    long long cross=cross_sum(a,lo,mid,hi);
    long long best=left>right ? left:right;
    return best>cross ? best:cross;
}

