def quad(a, r, c, n):
    value = a[r][c]
    if all(a[i][j] == value
           for i in range(r, r + n)
           for j in range(c, c + n)):
        return str(value)
    h = n // 2
    return ('(' + quad(a,r,c,h) + quad(a,r,c+h,h)
            + quad(a,r+h,c,h) + quad(a,r+h,c+h,h) + ')')

