/* out has >= 4*n*n+1 bytes; start *p=0. */
void quad(const int a[][32], int r, int c, int n,
          char out[], int *p) {
    int same=1, value=a[r][c];
    for (int i=r; i<r+n; ++i)
        for (int j=c; j<c+n; ++j)
            if (a[i][j]!=value) same=0;
    if (same) out[(*p)++]=(char)('0'+value);
    else {
        int h=n/2; out[(*p)++]='(';
        quad(a,r,c,h,out,p); quad(a,r,c+h,h,out,p);
        quad(a,r+h,c,h,out,p); quad(a,r+h,c+h,h,out,p);
        out[(*p)++]=')';
    }
    out[*p]='\0';
}

long long karatsuba(long long x, long long y) {
    if (x<10 || y<10) return x*y;
    long long t=x>y ? x:y, base=1;
    int digits=0;
    while (t) { ++digits; t/=10; }
    for (int i=0; i<digits/2; ++i) base*=10;
    long long a=x/base, b=x%base, c=y/base, d=y%base;
    long long ac=karatsuba(a,c), bd=karatsuba(b,d);
    long long cross=karatsuba(a+b,c+d)-ac-bd;
    return ac*base*base+cross*base+bd;
}

