def kruskal_cost(n, edges):
    parent = list(range(n))
    cost = used = 0
    for u, v, w in edges:
        ru, rv = dsu_find(parent,u), dsu_find(parent,v)
        if ru != rv:
            parent[ru] = rv
            cost += w
            used += 1
    return cost if used == n - 1 else -10**18

