    int parent[1000], used=0;
    long long cost=0;
    for (int i=0; i<n; ++i) parent[i]=i;
    for (int i=0; i<m; ++i) {
        int ru=dsu_find(parent,edges[i][0]);
        int rv=dsu_find(parent,edges[i][1]);
        if (ru!=rv) {
            parent[ru]=rv; cost+=edges[i][2]; ++used;
        }
    }
    return used==n-1 ? cost:-1000000000000000000LL;
}

