def dijkstra(g, s):
    n = len(g)
    dist, used = [10**18]*n, [False]*n
    dist[s] = 0
    for _ in range(n):
        u = pick_vertex(dist, used)
        if u == -1:
            break
        used[u] = True
        for v in range(n):
            if g[u][v] >= 0:
                dist[v] = min(dist[v], dist[u] + g[u][v])
    return dist

