long long nearest_tour(const int d[][50], int n) {
    int used[50]={0}, u=0;
    long long cost=0; used[0]=1;
    for (int step=1; step<n; ++step) {
        int v=-1;
        for (int i=0; i<n; ++i)
            if (!used[i] && (v==-1 || d[u][i]<d[u][v])) v=i;
        cost+=d[u][v]; used[v]=1; u=v;
    }
    return cost+d[u][0];
}

