int make_path(int n, const int dp[], int out[]) {
    int length=0, divisors[]={2,3,5};
    out[length++]=n;
    while (n>1) {
        int next=n-1;
        if (dp[next]+1!=dp[n]) {
            for (int j=0; j<3; ++j) {
                int d=divisors[j];
                if (n%d==0 && dp[n/d]+1==dp[n]) {next=n/d; break;}
            }
        }
        n=next; out[length++]=n;
    }
    return length;
}

