def knapsack2(items, W):
    dp = [[0]*(W+1) for _ in range(len(items)+1)]
    for i, (w,v) in enumerate(items, 1):
        for c in range(W+1):
            dp[i][c] = dp[i-1][c]
            if w <= c:
                dp[i][c] = max(dp[i][c], dp[i-1][c-w]+v)
    return dp[len(items)][W]

