    for (int i=1; i<=n; ++i) {
        for (int c=0; c<=W; ++c) {
            dp[i][c]=dp[i-1][c];
            if (w[i-1]<=c) {
                int take=dp[i-1][c-w[i-1]]+v[i-1];
                if (take>dp[i][c]) dp[i][c]=take;
            }
        }
    }
    return dp[n][W];
}

