    for (int j=0; j<=n; ++j) dp[0][j]=0;
    for (int i=1; i<=m; ++i)
        for (int j=1; j<=n; ++j) {
            if (a[i-1]==b[j-1]) dp[i][j]=dp[i-1][j-1]+1;
            else dp[i][j]=dp[i-1][j]>dp[i][j-1]
                          ? dp[i-1][j]:dp[i][j-1];
        }
    return dp[m][n];
}

