void lcs_restore(const char a[], const char b[], int m, int n,
                 const int dp[][101], char out[]) {
    int i=m, j=n, k=0;
    while (i>0 && j>0) {
        if (a[i-1]==b[j-1]) {out[k++]=a[i-1]; --i; --j;}
        else if (dp[i-1][j]>=dp[i][j-1]) --i;
        else --j;
    }
    out[k]='\0';
    for (i=0; i<k/2; ++i) {
        char t=out[i]; out[i]=out[k-1-i]; out[k-1-i]=t;
    }
}

