def grid_cost(a):
    rows, cols = len(a), len(a[0])
    dp = [[10**18]*cols for _ in range(rows)]
    dp[0][0] = a[0][0]
    for i in range(rows):
        for j in range(cols):
            if i: dp[i][j] = min(dp[i][j], dp[i-1][j]+a[i][j])
            if j: dp[i][j] = min(dp[i][j], dp[i][j-1]+a[i][j])
            if i and j:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1]+a[i][j]//2)
    return dp[-1][-1]

