long long grid_cost(const int a[][100], int rows, int cols,
                    long long dp[][100]) {
    for (int i=0; i<rows; ++i) {
        for (int j=0; j<cols; ++j) {
            long long best=1000000000000000000LL, t;
            if (i==0 && j==0) best=a[0][0];
            if (i) {t=dp[i-1][j]+a[i][j]; if(t<best) best=t;}
            if (j) {t=dp[i][j-1]+a[i][j]; if(t<best) best=t;}
            if (i && j) {
                t=dp[i-1][j-1]+a[i][j]/2; if(t<best) best=t;
            }
            dp[i][j]=best;
        }
    }
    return dp[rows-1][cols-1];
}
